import {rank,requirements,brief,METHOD} from './core.js';
const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='patent2market-workspace-v1';let state={problem:'',constraints:'',saved:[],notes:{}};try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&typeof stored==='object')state={problem:typeof stored.problem==='string'?stored.problem:'',constraints:typeof stored.constraints==='string'?stored.constraints:'',saved:Array.isArray(stored.saved)?stored.saved.filter(x=>typeof x==='string'):[],notes:stored.notes&&typeof stored.notes==='object'?stored.notes:{}};}catch{}
let catalog,mode='discover',limit=12,query=state.problem,timer;const dialog=$('#detail');
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Browser storage unavailable. Export your brief to keep your work.');}}
function sync(){state.problem=$('#problem').value;state.constraints=$('#constraints').value;persist();}
function selected(){return catalog.records.filter(r=>state.saved.includes(r.id));}
function open(content){$('#dialog-content').innerHTML=content;dialog.showModal();}
function render(){if(!catalog)return;$('#saved-count').textContent=selected().length;$('#discover').classList.toggle('active',mode==='discover');$('#saved').classList.toggle('active',mode==='saved');$('#results-title').textContent=mode==='saved'?'Your investigation shortlist':'Technology explorer';let results=rank(catalog.records,query);if(mode==='saved')results=selected().map(record=>({record,score:0,matched:[],expanded:[]}));const category=$('#category').value;if(category)results=results.filter(r=>r.record.category===category);$('#summary').textContent=mode==='saved'?`${results.length} saved technologies · stored on this device`:`${results.length} ${query?'matching':'available'} technologies${query?' · ranked by text relevance':' · explore a field or describe a problem'}`;$('#export').disabled=!selected().length;$('#compare').disabled=selected().length<2;$('#results').innerHTML=results.slice(0,limit).map(({record:r,matched,expanded,score})=>`<article class="card"><div class="card-top"><div><span class="badge">${escape(r.category||'Technology')}</span><span class="id">${escape(r.id)}</span></div><button class="save" data-save="${escape(r.id)}" aria-label="${state.saved.includes(r.id)?'Remove':'Save'} ${escape(r.title)}" aria-pressed="${state.saved.includes(r.id)}">${state.saved.includes(r.id)?'✓ Saved':'+ Save'}</button></div><h3>${escape(r.title)}</h3><p>${escape(r.description)}</p><div class="card-bottom"><span class="match">${score?`Matched: ${escape(matched.slice(0,5).join(', ')||'related concepts')}<br>Retrieval score ${score.toFixed(2)} · not a fit percentage`:`NASA ${escape(r.center)} · requirements unverified`}</span><button class="detail-button" data-detail="${escape(r.id)}">Examine evidence ↗</button></div></article>`).join('')||`<div class="empty">${mode==='saved'?'Your shortlist is empty. Save promising technologies as you explore.':'No matches in this snapshot. Try a technical function such as filtration, cooling, or sensing, or choose another field.'}</div>`;$('#more').hidden=results.length<=limit;}
function detail(id){const r=catalog.records.find(r=>r.id===id);if(!r)return;const result=rank([r],query)[0];open(`<span class="badge">${escape(r.category)}</span><h2>${escape(r.title)}</h2><p>${escape(r.id)} · NASA ${escape(r.center)}</p><h3>What the source reports</h3><div class="evidence">${escape(r.description)}</div><p><a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">Read the original NASA record ↗</a><br><small>Catalog retrieved ${escape(r.retrievedAt)}. This is a technology listing, not a verified patent-status record.</small></p><h3>Why this appeared</h3><p>${result?.matched.length?`Your terms found in the record: ${escape(result.matched.join(', '))}.`:'Explore the source to determine whether this technology addresses your need.'} ${result?.expanded.length?`Related search vocabulary: ${escape(result.expanded.join(', '))}.`:''}</p><h3>Your requirements</h3>${requirements(state.constraints).map(c=>`<div class="requirement"><span>${escape(c)}</span><span class="unknown">Not assessed</span></div>`).join('')||'<p>No requirements added yet. Define operating conditions, cost, and maintenance constraints in your challenge.</p>'}<h3>What remains to be established</h3><p>Performance in your setting, technology readiness, implementation cost, and licensing or patent status are not verified by this catalog.</p><h3>Investigation notes</h3><label for="notes">Evidence, open questions, and next steps</label><textarea id="notes" rows="4" maxlength="12000" placeholder="What would you need to test or ask the technology owner?">${escape(state.notes[id]||'')}</textarea><button class="secondary" id="detail-save">${state.saved.includes(id)?'Remove from shortlist':'Save to shortlist'}</button>`);$('#notes').addEventListener('input',e=>{state.notes[id]=e.target.value;persist();});$('#detail-save').onclick=()=>{toggle(id);$('#detail-save').textContent=state.saved.includes(id)?'Remove from shortlist':'Save to shortlist';};}
function toggle(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();}
$('#problem').value=state.problem;$('#constraints').value=state.constraints;$('#problem').addEventListener('input',sync);$('#constraints').addEventListener('input',sync);
$('#search-form').onsubmit=e=>{e.preventDefault();sync();query=state.problem;mode='discover';limit=12;render();};
document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#problem').value=b.dataset.query;sync();query=state.problem;mode='discover';limit=12;$('#category').value='';render();});
$('#category').onchange=()=>{limit=12;render();};$('#more').onclick=()=>{limit+=12;render();};$('#discover').onclick=()=>{mode='discover';limit=12;render();};$('#saved').onclick=()=>{mode='saved';limit=12;$('#category').value='';render();};
$('#results').onclick=e=>{const save=e.target.closest('[data-save]'),link=e.target.closest('[data-detail]');if(save)toggle(save.dataset.save);if(link)detail(link.dataset.detail);};
$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
$('#export').onclick=()=>{sync();const url=URL.createObjectURL(new Blob([brief(selected(),state.problem,state.constraints,state.notes)],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='patent2market-investigation.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Investigation brief exported');};
$('#compare').onclick=()=>{const list=selected().slice(0,6);open(`<h2>Compare your shortlist</h2><p>Compare source descriptions and unanswered requirements. ${selected().length>6?'Showing the first six saved technologies.':''}</p><div class="table-wrap"><table><thead><tr><th scope="col">Evidence</th>${list.map(r=>`<th scope="col">${escape(r.title)}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">Source description</th>${list.map(r=>`<td>${escape(r.description)}</td>`).join('')}</tr><tr><th scope="row">Field</th>${list.map(r=>`<td>${escape(r.category)}</td>`).join('')}</tr>${requirements(state.constraints).map(c=>`<tr><th scope="row">${escape(c)}</th>${list.map(()=>'<td>Not assessed</td>').join('')}</tr>`).join('')}<tr><th scope="row">Readiness / cost / rights</th>${list.map(()=>'<td>Require verification</td>').join('')}</tr><tr><th scope="row">Your notes</th>${list.map(r=>`<td>${escape(state.notes[r.id]||'None yet')}</td>`).join('')}</tr><tr><th scope="row">Original record</th>${list.map(r=>`<td><a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">NASA record ↗</a></td>`).join('')}</tr></tbody></table></div>`);};
$('#about').onclick=()=>open(`<h2>Useful leads. Visible evidence.</h2><p>Patent2Market helps you explore existing technologies as starting points for real-world solutions. This first release searches a local snapshot of NASA Technology Transfer listings.</p><h3>How discovery works</h3><p>Search uses BM25-style lexical ranking with title weighting and a small, inspectable concept vocabulary. It does not use an LLM or semantic embedding model. Scores rank textual relevance; they do not measure technical feasibility or commercial potential.</p><p>Method: <code>${METHOD}</code>. Requirements are carried into comparisons and exported briefs, but are not automatically assessed.</p><h3>Coverage and provenance</h3><p>${catalog?escape(catalog.records.length):'—'} records, retrieved ${catalog?escape(catalog.version):'—'}. The snapshot combines searches for water, thermal, energy, sensors, agriculture, manufacturing, filtration, and batteries. It is not a complete patent search.</p><p><a href="https://technology.nasa.gov/api/" target="_blank" rel="noopener noreferrer">NASA source API</a> · <a href="./catalog.json" download>Download the catalog</a></p><h3>Technology access</h3><p>Public access to a description does not establish a right to practice an invention. Patent status and licensing availability are unverified here. Follow the source record and confirm with the technology owner before implementation. NASA does not endorse this application.</p><h3>Privacy and offline access</h3><p>Your problem, shortlist, and notes remain in browser storage. No analytics, accounts, or remote AI calls. After the initial assets finish caching, the application works offline. Storage is specific to this browser and may be cleared by your browser; export important work. Optional installation is supported on compatible browsers.</p><h3>Open-source foundation</h3><p>Original application code is MIT licensed. No third-party JavaScript, fonts, images, or runtime packages are included. NASA source material is separately attributed; application licensing does not license the underlying inventions.</p>`);
$('#reset').onclick=()=>{open('<h2>Clear this workspace?</h2><p>This removes your problem, requirements, saved technologies, and notes from this browser. Export a brief first if you need a copy.</p><button id="confirm-reset" class="secondary">Clear local workspace</button>');$('#confirm-reset').onclick=()=>{state={problem:'',constraints:'',saved:[],notes:{}};query='';$('#problem').value='';$('#constraints').value='';$('#category').value='';persist();mode='discover';dialog.close();render();notify('Workspace cleared');};};
function connection(){ $('#connection').textContent=navigator.onLine?'Local-first workspace':'Offline workspace';}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
try{const response=await fetch('./catalog.json');if(!response.ok)throw Error('Catalog unavailable');catalog=await response.json();if(!Array.isArray(catalog.records))throw Error('Invalid catalog');$('#catalog-count').textContent=`${catalog.records.length} NASA records`;$('#snapshot').textContent=catalog.version;[...new Set(catalog.records.map(r=>r.category).filter(Boolean))].sort().forEach(c=>{const option=document.createElement('option');option.value=c;option.textContent=c;$('#category').append(option);});render();}catch{$('#summary').textContent='The catalog could not load. Reconnect and reload to download the offline snapshot.';$('#results').innerHTML='<div class="empty">Technology data is unavailable. Your saved workspace has not been changed.</div>';$('#export').disabled=true;$('#compare').disabled=true;}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{if(navigator.onLine)$('#connection').textContent='Ready for offline use';}).catch(()=>{if(navigator.onLine)$('#connection').textContent='Online · offline cache unavailable';});
